import type { CSSProperties, PropType, Ref } from 'vue'
import type { ThemeProps } from '../../_mixins'
import type { ExtractPublicPropTypes } from '../../_utils'
import type { DividerTheme, DividerThemeOverrides } from '../styles'
import { computed, defineComponent, Fragment, h } from 'vue'
import { useConfig, useTheme, useThemeClass } from '../../_mixins'
import { dividerLight } from '../styles'
import style from './styles/index.cssr'

export const dividerProps = {
  ...(useTheme.props as ThemeProps<DividerTheme, DividerThemeOverrides>),
  titlePlacement: {
    type: String as PropType<'left' | 'center' | 'right'>,
    default: 'center'
  },
  dashed: Boolean,
  vertical: Boolean
} as const

export type DividerProps = ExtractPublicPropTypes<typeof dividerProps>

export default defineComponent({
  name: 'Divider',
  props: dividerProps,
  setup(props) {
    const { mergedClsPrefixRef, inlineThemeDisabled } = useConfig(props)
    const themeRef = useTheme(
      'Divider',
      '-divider',
      style,
      dividerLight,
      props,
      mergedClsPrefixRef
    )
    const cssVarsRef = computed(() => {
      const {
        common: { cubicBezierEaseInOut },
        self: { color, textColor, fontWeight }
      } = themeRef.value
      return {
        '--n-bezier': cubicBezierEaseInOut,
        '--n-color': color,
        '--n-text-color': textColor,
        '--n-font-weight': fontWeight
      }
    })
    const themeClassHandle = inlineThemeDisabled
      ? useThemeClass('divider', undefined, cssVarsRef, props)
      : undefined
    return {
      mergedClsPrefix: mergedClsPrefixRef,
      cssVars: inlineThemeDisabled
        ? undefined
        : (cssVarsRef as Ref<CSSProperties>),
      themeClass: themeClassHandle?.themeClass,
      onRender: themeClassHandle?.onRender
    }
  },
  render() {
    const {
      $slots,
      titlePlacement,
      vertical,
      dashed,
      cssVars,
      mergedClsPrefix
    } = this
    this.onRender?.()
    return (
      <div
        role="separator"
        class={[
          `${mergedClsPrefix}-divider`,
          this.themeClass,
          {
            [`${mergedClsPrefix}-divider--vertical`]: vertical,
            [`${mergedClsPrefix}-divider--no-title`]: !$slots.default,
            [`${mergedClsPrefix}-divider--dashed`]: dashed,
            [`${mergedClsPrefix}-divider--title-position-${titlePlacement}`]:
              $slots.default && titlePlacement
          }
        ]}
        style={cssVars as CSSProperties}
      >
        {!vertical ? (
          <div
            class={`${mergedClsPrefix}-divider__line ${mergedClsPrefix}-divider__line--left`}
          />
        ) : null}
        {!vertical && $slots.default ? (
          <>
            <div class={`${mergedClsPrefix}-divider__title`}>
              {this.$slots.default?.()}
            </div>
            <div
              class={`${mergedClsPrefix}-divider__line ${mergedClsPrefix}-divider__line--right`}
            />
          </>
        ) : null}
      </div>
    )
  }
})

import { cB, cE, cM, cNotM } from '../../../_utils/cssr'

// vars:
// --n-bezier
// --n-color
// --n-text-color
// --n-font-weight
export default cB('divider', `
  position: relative;
  display: flex;
  width: 100%;
  box-sizing: border-box;
  font-size: 16px;
  color: var(--n-text-color);
  transition:
    color .3s var(--n-bezier),
    background-color .3s var(--n-bezier);
`, [
  cNotM('vertical', `
    margin-top: 24px;
    margin-bottom: 24px;
  `, [
    cNotM('no-title', `
      display: flex;
      align-items: center;
    `)
  ]),
  cE('title', `
    display: flex;
    align-items: center;
    margin-left: 12px;
    margin-right: 12px;
    white-space: nowrap;
    font-weight: var(--n-font-weight);
  `),
  cM('title-position-left', [
    cE('line', [
      cM('left', {
        width: '28px'
      })
    ])
  ]),
  cM('title-position-right', [
    cE('line', [
      cM('right', {
        width: '28px'
      })
    ])
  ]),
  cM('dashed', [
    cE('line', `
      background-color: #0000;
      height: 0px;
      width: 100%;
      border-style: dashed;
      border-width: 1px 0 0;
    `)
  ]),
  cM('vertical', `
    display: inline-block;
    height: 1em;
    margin: 0 8px;
    vertical-align: middle;
    width: 1px;
  `),
  cE('line', `
    border: none;
    transition: background-color .3s var(--n-bezier), border-color .3s var(--n-bezier);
    height: 1px;
    width: 100%;
    margin: 0;
  `),
  cNotM('dashed', [
    cE('line', {
      backgroundColor: 'var(--n-color)'
    })
  ]),
  cM('dashed', [
    cE('line', {
      borderColor: 'var(--n-color)'
    })
  ]),
  cM('vertical', {
    backgroundColor: 'var(--n-color)'
  })
])

import type {
  CSSProperties,
  ImgHTMLAttributes,
  PropType,
  Ref,
  SlotsType,
  VNode,
  VNodeChild
} from 'vue'
import type { ThemeProps } from '../../_mixins'
import type { ExtractPublicPropTypes } from '../../_utils'
import type { IntersectionObserverOptions } from '../../image/src/utils'
import type { AvatarTheme, AvatarThemeOverrides } from '../styles'
import type { ObjectFit, Size } from './interface'
import {
  computed,
  defineComponent,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
  watchEffect
} from 'vue'
import { VResizeObserver } from 'vueuc'
import { useConfig, useTheme, useThemeClass } from '../../_mixins'
import {
  color2Class,
  createKey,
  resolveSlot,
  resolveWrappedSlot
} from '../../_utils'
import { isImageSupportNativeLazy } from '../../_utils/env/is-native-lazy-load'
import { observeIntersection } from '../../image/src/utils'
import { tagInjectionKey } from '../../tag/src/Tag'
import { avatarLight } from '../styles'
import { avatarGroupInjectionKey } from './context'
import style from './styles/index.cssr'

export const avatarProps = {
  ...(useTheme.props as ThemeProps<AvatarTheme, AvatarThemeOverrides>),
  size: [String, Number] as PropType<Size>,
  src: String,
  circle: {
    type: Boolean,
    default: undefined
  },
  objectFit: String as PropType<ObjectFit>,
  round: {
    type: Boolean,
    default: undefined
  },
  bordered: {
    type: Boolean,
    default: undefined
  },
  onError: Function as PropType<(e: Event) => void>,
  fallbackSrc: String,
  intersectionObserverOptions: Object as PropType<IntersectionObserverOptions>,
  lazy: Boolean,
  onLoad: Function as PropType<(e: Event) => void>,
  renderPlaceholder: Function as PropType<() => VNodeChild>,
  renderFallback: Function as PropType<() => VNodeChild>,
  imgProps: Object as PropType<ImgHTMLAttributes>,
  /** @deprecated */
  color: String
} as const

export type AvatarProps = ExtractPublicPropTypes<typeof avatarProps>

export interface AvatarSlots {
  default?: () => VNode[]
  placeholder?: () => VNode[]
  fallback?: () => VNode[]
}

export default defineComponent({
  name: 'Avatar',
  props: avatarProps,
  slots: Object as SlotsType<AvatarSlots>,
  setup(props) {
    const { mergedClsPrefixRef, inlineThemeDisabled } = useConfig(props)
    const hasLoadErrorRef = ref(false)
    let memoedTextHtml: string | null = null
    const textRef = ref<HTMLElement | null>(null)
    const selfRef = ref<HTMLElement | null>(null)
    const fitTextTransform = (): void => {
      const { value: textEl } = textRef
      if (textEl) {
        if (memoedTextHtml === null || memoedTextHtml !== textEl.innerHTML) {
          memoedTextHtml = textEl.innerHTML
          const { value: selfEl } = selfRef
          if (selfEl) {
            const { offsetWidth: elWidth, offsetHeight: elHeight } = selfEl
            const { offsetWidth: textWidth, offsetHeight: textHeight } = textEl
            const radix = 0.9
            const ratio = Math.min(
              (elWidth / textWidth) * radix,
              (elHeight / textHeight) * radix,
              1
            )
            textEl.style.transform = `translateX(-50%) translateY(-50%) scale(${ratio})`
          }
        }
      }
    }
    const NAvatarGroup = inject(avatarGroupInjectionKey, null)
    const mergedSizeRef = computed(() => {
      const { size } = props
      if (size)
        return size
      const { size: avatarGroupSize } = NAvatarGroup || {}
      if (avatarGroupSize)
        return avatarGroupSize
      return 'medium'
    })
    const themeRef = useTheme(
      'Avatar',
      '-avatar',
      style,
      avatarLight,
      props,
      mergedClsPrefixRef
    )
    const TagInjection = inject(tagInjectionKey, null)
    const mergedRoundRef = computed(() => {
      if (NAvatarGroup)
        return true
      const { round, circle } = props
      if (round !== undefined || circle !== undefined)
        return round || circle
      if (TagInjection) {
        return TagInjection.roundRef.value
      }
      return false
    })
    const mergedBorderedRef = computed(() => {
      if (NAvatarGroup)
        return true
      return props.bordered || false
    })
    const cssVarsRef = computed(() => {
      const size = mergedSizeRef.value
      const round = mergedRoundRef.value
      const bordered = mergedBorderedRef.value
      const { color: propColor } = props
      const {
        self: {
          borderRadius,
          fontSize,
          color,
          border,
          colorModal,
          colorPopover
        },
        common: { cubicBezierEaseInOut }
      } = themeRef.value
      let height: string
      if (typeof size === 'number') {
        height = `${size}px`
      }
      else {
        height = themeRef.value.self[createKey('height', size)]
      }
      return {
        '--n-font-size': fontSize,
        '--n-border': bordered ? border : 'none',
        '--n-border-radius': round ? '50%' : borderRadius,
        '--n-color': propColor || color,
        '--n-color-modal': propColor || colorModal,
        '--n-color-popover': propColor || colorPopover,
        '--n-bezier': cubicBezierEaseInOut,
        '--n-merged-size': `var(--n-avatar-size-override, ${height})`
      }
    })
    const themeClassHandle = inlineThemeDisabled
      ? useThemeClass(
          'avatar',
          computed(() => {
            const size = mergedSizeRef.value
            const round = mergedRoundRef.value
            const bordered = mergedBorderedRef.value
            const { color } = props
            let hash = ''
            if (size) {
              if (typeof size === 'number') {
                hash += `a${size}`
              }
              else {
                hash += size[0]
              }
            }
            if (round) {
              hash += 'b'
            }
            if (bordered) {
              hash += 'c'
            }
            if (color) {
              hash += color2Class(color)
            }
            return hash
          }),
          cssVarsRef,
          props
        )
      : undefined

    const shouldStartLoadingRef = ref(!props.lazy)

    onMounted(() => {
      // Use IntersectionObserver if lazy and intersectionObserverOptions is set
      if (props.lazy && props.intersectionObserverOptions) {
        let unobserve: (() => void) | undefined
        const stopWatchHandle = watchEffect(() => {
          unobserve?.()
          unobserve = undefined
          if (props.lazy) {
            unobserve = observeIntersection(
              selfRef.value,
              props.intersectionObserverOptions,
              shouldStartLoadingRef
            )
          }
        })
        onBeforeUnmount(() => {
          stopWatchHandle()
          unobserve?.()
        })
      }
    })

    watch(
      () => props.src || props.imgProps?.src,
      () => {
        hasLoadErrorRef.value = false
      }
    )

    const loadedRef = ref(!props.lazy)

    return {
      textRef,
      selfRef,
      mergedRoundRef,
      mergedClsPrefix: mergedClsPrefixRef,
      fitTextTransform,
      cssVars: inlineThemeDisabled
        ? undefined
        : (cssVarsRef as Ref<CSSProperties>),
      themeClass: themeClassHandle?.themeClass,
      onRender: themeClassHandle?.onRender,
      hasLoadError: hasLoadErrorRef,
      shouldStartLoading: shouldStartLoadingRef,
      loaded: loadedRef,
      mergedOnError: (e: Event) => {
        if (!shouldStartLoadingRef.value)
          return
        hasLoadErrorRef.value = true
        const { onError, imgProps: { onError: imgPropsOnError } = {} } = props
        onError?.(e)
        imgPropsOnError?.(e)
      },
      mergedOnLoad: (e: Event) => {
        const { onLoad, imgProps: { onLoad: imgPropsOnLoad } = {} } = props
        onLoad?.(e)
        imgPropsOnLoad?.(e)
        loadedRef.value = true
      }
    }
  },
  render() {
    const {
      $slots,
      src,
      mergedClsPrefix,
      lazy,
      onRender,
      loaded,
      hasLoadError,
      imgProps = {}
    } = this
    onRender?.()
    let img: VNodeChild
    const placeholderNode
      = !loaded
        && !hasLoadError
        && (this.renderPlaceholder
          ? this.renderPlaceholder()
          : this.$slots.placeholder?.())

    if (this.hasLoadError) {
      img = this.renderFallback
        ? this.renderFallback()
        : resolveSlot($slots.fallback, () => [
            <img src={this.fallbackSrc} style={{ objectFit: this.objectFit }} />
          ])
    }
    else {
      img = resolveWrappedSlot($slots.default, (children) => {
        if (children) {
          return (
            <VResizeObserver onResize={this.fitTextTransform}>
              {{
                default: () => (
                  <span ref="textRef" class={`${mergedClsPrefix}-avatar__text`}>
                    {children}
                  </span>
                )
              }}
            </VResizeObserver>
          )
        }
        else if (src || imgProps.src) {
          const loadSrc = this.src || imgProps.src
          return h('img', {
            ...imgProps,
            loading:
              // If interseciton observer options is set, do not use native lazy
              isImageSupportNativeLazy
              && !this.intersectionObserverOptions
              && lazy
                ? 'lazy'
                : 'eager',
            src:
              lazy && this.intersectionObserverOptions
                ? this.shouldStartLoading
                  ? loadSrc
                  : undefined
                : loadSrc,
            'data-image-src': loadSrc,
            onLoad: this.mergedOnLoad,
            onError: this.mergedOnError,
            style: [
              imgProps.style || '',
              { objectFit: this.objectFit },
              placeholderNode
                ? {
                    height: '0',
                    width: '0',
                    visibility: 'hidden',
                    position: 'absolute'
                  }
                : ''
            ]
          })
        }
      })
    }
    return (
      <span
        ref="selfRef"
        class={[`${mergedClsPrefix}-avatar`, this.themeClass]}
        style={this.cssVars as any}
      >
        {img}
        {lazy && placeholderNode}
      </span>
    )
  }
})

import { c, cB, cE, insideModal, insidePopover } from '../../../_utils/cssr'

// vars:
// --n-font-size
// --n-border-radius
// --n-color
// --n-color-modal
// --n-color-popover
// --n-bezier
// --n-merged-size
export default cB('avatar', `
  width: var(--n-merged-size);
  height: var(--n-merged-size);
  color: #FFF;
  font-size: var(--n-font-size);
  display: inline-flex;
  position: relative;
  overflow: hidden;
  text-align: center;
  border: var(--n-border);
  border-radius: var(--n-border-radius);
  --n-merged-color: var(--n-color);
  background-color: var(--n-merged-color);
  transition:
    border-color .3s var(--n-bezier),
    background-color .3s var(--n-bezier),
    color .3s var(--n-bezier);
`, [
  insideModal(c('&', '--n-merged-color: var(--n-color-modal);')),
  insidePopover(c('&', '--n-merged-color: var(--n-color-popover);')),
  c('img', `
    width: 100%;
    height: 100%;
  `),
  cE('text', `
    white-space: nowrap;
    display: inline-block;
    position: absolute;
    left: 50%;
    top: 50%;
  `),
  cB('icon', `
    vertical-align: bottom;
    font-size: calc(var(--n-merged-size) - 6px);
  `),
  cE('text', 'line-height: 1.25')
])

import type { CSSProperties, PropType } from 'vue'
import type { ThemeProps } from '../../_mixins'
import type { ExtractPublicPropTypes } from '../../_utils'
import type { SpaceTheme, SpaceThemeOverrides } from '../styles'
import type { SpaceSize } from './public-types'
import { depx, getGap } from 'seemly'
import { Comment, computed, defineComponent, h } from 'vue'
import { useConfig, useTheme } from '../../_mixins'
import { useRtl } from '../../_mixins/use-rtl'
import { createKey, flatten, getSlot } from '../../_utils'
import { spaceLight } from '../styles'
import { ensureSupportFlexGap } from './utils'

type Align
  = | 'stretch'
    | 'baseline'
    | 'start'
    | 'end'
    | 'center'
    | 'flex-end'
    | 'flex-start'

export type Justify
  = 'start' | 'end' | 'center' | 'space-around' | 'space-between' | 'space-evenly'

export const spaceProps = {
  ...(useTheme.props as ThemeProps<SpaceTheme, SpaceThemeOverrides>),
  align: String as PropType<Align>,
  justify: {
    type: String as PropType<Justify>,
    default: 'start'
  },
  inline: Boolean,
  vertical: Boolean,
  reverse: Boolean,
  size: [String, Number, Array] as PropType<SpaceSize>,
  wrapItem: {
    type: Boolean,
    default: true
  },
  itemClass: String,
  itemStyle: [String, Object] as PropType<string | CSSProperties>,
  wrap: {
    type: Boolean,
    default: true
  },
  // internal
  internalUseGap: {
    type: Boolean,
    default: undefined
  }
} as const

export type SpaceProps = ExtractPublicPropTypes<typeof spaceProps>

export default defineComponent({
  name: 'Space',
  props: spaceProps,
  setup(props) {
    const { mergedClsPrefixRef, mergedRtlRef, mergedComponentPropsRef }
      = useConfig(props)
    const mergedSizeRef = computed<SpaceSize>(() => {
      return (
        props.size ?? mergedComponentPropsRef?.value?.Space?.size ?? 'medium'
      )
    })
    const themeRef = useTheme(
      'Space',
      '-space',
      undefined,
      spaceLight,
      props,
      mergedClsPrefixRef
    )
    const rtlEnabledRef = useRtl('Space', mergedRtlRef, mergedClsPrefixRef)
    return {
      useGap: ensureSupportFlexGap(),
      rtlEnabled: rtlEnabledRef,
      mergedClsPrefix: mergedClsPrefixRef,
      margin: computed<{ horizontal: number, vertical: number }>(() => {
        const size = mergedSizeRef.value
        if (Array.isArray(size)) {
          return {
            horizontal: size[0],
            vertical: size[1]
          }
        }
        if (typeof size === 'number') {
          return {
            horizontal: size,
            vertical: size
          }
        }
        const {
          self: { [createKey('gap', size)]: gap }
        } = themeRef.value
        const { row, col } = getGap(gap)
        return {
          horizontal: depx(col),
          vertical: depx(row)
        }
      })
    }
  },
  render() {
    const {
      vertical,
      reverse,
      align,
      inline,
      justify,
      itemClass,
      itemStyle,
      margin,
      wrap,
      mergedClsPrefix,
      rtlEnabled,
      useGap,
      wrapItem,
      internalUseGap
    } = this
    const children = flatten(getSlot(this), false)
    if (!children.length)
      return null
    const horizontalMargin = `${margin.horizontal}px`
    const semiHorizontalMargin = `${margin.horizontal / 2}px`
    const verticalMargin = `${margin.vertical}px`
    const semiVerticalMargin = `${margin.vertical / 2}px`
    const lastIndex = children.length - 1
    const isJustifySpace = justify.startsWith('space-')
    return (
      <div
        role="none"
        class={[
          `${mergedClsPrefix}-space`,
          rtlEnabled && `${mergedClsPrefix}-space--rtl`
        ]}
        style={{
          display: inline ? 'inline-flex' : 'flex',
          flexDirection: (() => {
            if (vertical && !reverse)
              return 'column'
            if (vertical && reverse)
              return 'column-reverse'
            if (!vertical && reverse)
              return 'row-reverse'
            /** (!vertical && !reverse) */ else return 'row'
          })(),
          justifyContent: ['start', 'end'].includes(justify)
            ? `flex-${justify}`
            : justify,
          flexWrap: !wrap || vertical ? 'nowrap' : 'wrap',
          marginTop: useGap || vertical ? '' : `-${semiVerticalMargin}`,
          marginBottom: useGap || vertical ? '' : `-${semiVerticalMargin}`,
          alignItems: align,
          gap: useGap ? `${margin.vertical}px ${margin.horizontal}px` : ''
        }}
      >
        {!wrapItem && (useGap || internalUseGap)
          ? children
          : children.map((child, index) =>
              child.type === Comment ? (
                child
              ) : (
                <div
                  role="none"
                  class={itemClass}
                  style={[
                    itemStyle as any,
                    {
                      maxWidth: '100%'
                    },
                    useGap
                      ? ''
                      : vertical
                        ? {
                            marginBottom:
                              index !== lastIndex ? verticalMargin : ''
                          }
                        : rtlEnabled
                          ? {
                              marginLeft: isJustifySpace
                                ? justify === 'space-between'
                                && index === lastIndex
                                  ? ''
                                  : semiHorizontalMargin
                                : index !== lastIndex
                                  ? horizontalMargin
                                  : '',
                              marginRight: isJustifySpace
                                ? justify === 'space-between' && index === 0
                                  ? ''
                                  : semiHorizontalMargin
                                : '',
                              paddingTop: semiVerticalMargin,
                              paddingBottom: semiVerticalMargin
                            }
                          : {
                              marginRight: isJustifySpace
                                ? justify === 'space-between'
                                && index === lastIndex
                                  ? ''
                                  : semiHorizontalMargin
                                : index !== lastIndex
                                  ? horizontalMargin
                                  : '',
                              marginLeft: isJustifySpace
                                ? justify === 'space-between' && index === 0
                                  ? ''
                                  : semiHorizontalMargin
                                : '',
                              paddingTop: semiVerticalMargin,
                              paddingBottom: semiVerticalMargin
                            }
                  ]}
                >
                  {child}
                </div>
              )
            )}
      </div>
    )
  }
})

import { isBrowser } from '../../_utils'

let supportFlexGap: boolean | undefined

export function ensureSupportFlexGap(): boolean {
  if (!isBrowser)
    return true
  if (supportFlexGap === undefined) {
    // create flex container with row-gap set
    const flex = document.createElement('div')
    flex.style.display = 'flex'
    flex.style.flexDirection = 'column'
    flex.style.rowGap = '1px'

    // create two, elements inside it
    flex.appendChild(document.createElement('div'))
    flex.appendChild(document.createElement('div'))

    // append to the DOM (needed to obtain scrollHeight)
    document.body.appendChild(flex)
    const isSupported = flex.scrollHeight === 1 // flex container should be 1px high from the row-gap
    document.body.removeChild(flex)
    return (supportFlexGap = isSupported)
  }
  return supportFlexGap
}

import type { ExtractThemeOverrides, Theme } from '../../_mixins'
import commonVars from './_common'

function self() {
  return commonVars
}

export interface SpaceThemeVars extends ReturnType<typeof self> {}

const spaceLight: SpaceTheme = {
  name: 'Space',
  self
}

export interface SpaceTheme extends Theme<'Space', SpaceThemeVars> {}

export interface SpaceThemeOverrides extends ExtractThemeOverrides<SpaceTheme> {}

export default spaceLight

{
  "pattern": "n-avatar",
  "mode": "regex",
